const crypto = require('crypto');
function isEnabled(flag, userId) {
  if (!flag.on) return false;
  const h = crypto.createHash('sha256').update(flag.name + ':' + userId).digest();
  return h.readUInt32BE(0) % 100 < flag.percent;
}
```
`Math.random()` isn't deterministic, so the same user would see the feature appear and disappear between requests. Hashing gives a stable bucket per user.
